import { Book } from "@/lib/types";

export const hosea: Book = {
  id: "hosea",
  name: "Hosea",
  shortName: "Hos",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Das Wort des HERRN, das zu Hosea, dem Sohn des Beeri, geschah in den Tagen des Usija, Jotam, Ahas, Hiskia, der Könige von Juda*, und in den Tagen des Jerobeam, des Sohnes des Joasch, des Königs von Israel*.", heading: "Hoseas Ehe und Kinder", footnotes: ["℘ Jes 1,1; Mi 1,1", "℘ 2Kö 14,23; Am 1,1"] },
      { number: 2, text: "Als der HERR anfing, mit Hosea zu reden, da sprach der HERR* zu Hosea: Geh, nimm dir eine hurerische Frau und zeuge hurerische Kinder*! Denn das Land treibt ständig Hurerei, vom HERRN hinweg*.", footnotes: ["o. Anfang vom Reden des HERRN durch Hosea: Der HERR sprach", "o. Hurenkinder\n℘ Kap. 3,1", "w. hurt und hurt von der Nachfolge hinter dem HERRN weg\n℘ Kap. 2,7; 5,3; 2Mo 34,16; 5Mo 31,16; Jer 2,20-23; Hes 16,15"] },
      { number: 3, text: "Da ging er und nahm Gomer, die Tochter Diblajims; und sie wurde schwanger und gebar ihm einen Sohn." },
      { number: 4, text: "Und der HERR sprach zu ihm: Gib ihm den Namen* Jesreel*! Denn nur ein Weilchen noch, dann suche ich die Blutschuld von Jesreel* am Haus Jehu heim und mache dem Königtum des Hauses Israel ein Ende*.", footnotes: ["℘ Jes 8,3", "d. h. Gott sät\n℘ Jos 19,18", "℘ 2Kö 10,1-11", "℘ 2Kö 17,6"] },
      { number: 5, text: "Und es wird geschehen an jenem Tag, da zerbreche ich den Bogen Israels in der Ebene Jesreel. —" },
      { number: 6, text: "Und sie wurde wieder schwanger und gebar eine Tochter. Und er sprach zu ihm: Gib ihr den Namen Lo-Ruhama*! Denn ich erbarme mich künftig über das Haus Israel nicht mehr*, sondern nehme ihnen mein Erbarmen völlig weg*.", footnotes: ["d. h. Nicht-Erbarmen\n℘ Kap. 2,25", "℘ 2Kö 17,20; Am 7,8; 9,8", "o. sondern verwerfe sie völlig (d. h. die Israeliten); o. dass ich ihnen irgendwie vergebe"] },
      { number: 7, text: "Aber über das Haus Juda erbarme ich mich und rette sie durch den HERRN, ihren Gott*. Doch ich rette sie nicht durch Bogen und durch Schwert und durch Krieg, durch Pferde und durch Reiter*. —", footnotes: ["℘ 2Mo 14,13; 2Kö 19,34", "℘ 2Kö 6,18; Ps 44,7; Sach 4,6"] },
      { number: 8, text: "Und als sie Lo-Ruhama* entwöhnt hatte, wurde sie wieder schwanger und gebar einen Sohn.", footnotes: ["d. h. Nicht-Erbarmen"] },
      { number: 9, text: "Und er sprach: Gib ihm den Namen Lo-Ammi*! Denn ihr seid nicht mein Volk, und ich, ich will nicht euer Gott sein*.", footnotes: ["d. h. Nicht-mein-Volk", "o. und ich bin nicht für euch der »Ich-bin«; vgl. 2Mo 3,14\n℘ Kap. 2,25"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Doch die Zahl der Söhne Israel wird wie Sand am Meer werden, den man nicht messen und nicht zählen kann*. Und es wird geschehen, an der Stelle, an der zu ihnen gesagt wurde*: Ihr seid nicht mein Volk!, wird zu ihnen gesagt werden: Söhne des lebendigen Gottes*.", footnotes: ["℘ 1Mo 22,17", "o. es wird geschehen: Statt dass man zu ihnen sagt; w. es wird geschehen, an dem Ort, an dem man sagt", "℘ V. 25; Röm 9,26"] },
      { number: 2, text: "Und die Söhne Juda und die Söhne Israel werden sich miteinander versammeln und sich ein gemeinsames Oberhaupt geben und aus dem Land heraufziehen*; denn groß ist der Tag von Jesreel*.", footnotes: ["o. und werden aus dem Boden sprossen; o. und werden sich des Landes bemächtigen\n℘ Jes 11,12.13; Mi 2,13", "d. h. Gott sät"] },
      { number: 3, text: "Sagt zu euren Brüdern: Mein Volk*! — und zu euren Schwestern: Erbarmen*!", footnotes: ["hebr. ammi", "hebr. ruhama\n℘ Jer 51,5"] },
      { number: 4, text: "Rechtet* mit eurer Mutter, rechtet! — denn sie ist nicht meine Frau, und ich bin nicht ihr Mann* —, damit sie ihre Hurerei von ihrem Gesicht entfernt und ihren Ehebruch zwischen ihren Brüsten*,", heading: "Gottes Scheidungsprozess gegen Israel", footnotes: ["o. Tretet in einen Rechtsstreit ein; o. Führt einen Rechtsstreit", "℘ Jes 50,1", "Gemeint sind die Merkmale der Prostituierten."] },
      { number: 5, text: "damit ich sie nicht nackt ausziehe* und sie hinstelle wie an dem Tag ihrer Geburt* und ich sie einer Wüste gleichmache* und sie wie dürres Land werden lasse und sie vor Durst sterben lasse*.", footnotes: ["℘ Jer 13,22; Hes 16,39", "℘ Hes 16,4", "℘ Jer 6,8", "℘ Am 8,13"] },
      { number: 6, text: "Auch über ihre Kinder werde ich mich nicht erbarmen, weil sie hurerische Kinder* sind*.", footnotes: ["o. Hurenkinder", "℘ Jes 57,3"] },
      { number: 7, text: "Denn ihre Mutter hat gehurt*; die mit ihnen schwanger ging, hat Schande getrieben. Denn sie sagte: Ich will meinen Liebhabern nachlaufen*, die mir mein Brot und mein Wasser geben*, meine Wolle und meinen Flachs, mein Öl und mein Getränk.", footnotes: ["℘ Kap. 1,2", "℘ Hes 23,12", "℘ 2Chr 28,23; Jer 44,17"] },
      { number: 8, text: "Darum: Siehe, ich will ihren* Weg mit Dornen verzäunen*, und ich will ihr eine Mauer errichten, dass sie ihre Pfade nicht finden kann.", footnotes: ["so mit LXX und syr. Üs.; Mas. T.: deinen", "℘ Hi 19,8"] },
      { number: 9, text: "Dann wird sie ihren Liebhabern nachjagen* und sie nicht erreichen, und sie wird sie suchen und nicht finden. Dann wird sie sagen: Ich will mich aufmachen und zu meinem ersten Mann zurückkehren*, denn damals ging es mir besser als jetzt.", footnotes: ["w. ihre Liebhaber verfolgen", "℘ Lk 15,18"] },
      { number: 10, text: "Aber sie erkannte nicht, dass ich es war, der ihr das Korn und den Most und das Öl gab, und dass ich ihr das Silber vermehrte und das Gold — sie aber haben es für den Baal verwendet*.", footnotes: ["℘ Kap. 10,1; 13,1; 2Chr 24,7; Hes 16,19"] },
      { number: 11, text: "Darum nehme ich mein Korn zurück zu seiner Zeit und meinen Most zu seiner Frist und entreiße ihr meine Wolle und meinen Flachs, die ihre Blöße bedecken sollten*.", footnotes: ["℘ Kap. 9,2; 3Mo 26,20"] },
      { number: 12, text: "Dann decke ich ihre Scham auf vor den Augen ihrer Liebhaber*, und niemand wird sie meiner Hand entreißen*.", footnotes: ["℘ Jer 13,26", "℘ Kap. 5,14"] },
      { number: 13, text: "Und ich mache ein Ende mit all ihrer Freude*, ihren Festen, ihren Neumonden und ihren Sabbaten und allen ihren Festzeiten*.", footnotes: ["℘ Jer 7,34; Kla 5,14", "℘ Kla 1,4; Am 8,10"] },
      { number: 14, text: "Und ich veröde ihren Weinstock und ihren Feigenbaum, von denen sie sagte: Die sind mein Liebeslohn, den mir meine Liebhaber gegeben haben*. Und ich mache sie zum Gestrüpp, dass die Tiere des Feldes sie abfressen*. —", footnotes: ["℘ Mi 1,7", "℘ Jes 5,5.6; Jer 45,4"] },
      { number: 15, text: "Und ich suche an ihr heim* die Festtage der Baalim, an denen sie ihnen Rauchopfer darbrachte und sich mit ihrem Ring und ihrem Halsgeschmeide schmückte und ihren Liebhabern nachlief; mich aber hat sie vergessen*, spricht der HERR*.", footnotes: ["℘ 1Kö 16,31", "℘ Ri 8,34", "w. ist der Ausspruch des HERRN"] },
      { number: 16, text: "Darum: Siehe, ich werde sie locken und sie in die Wüste führen* und ihr zu Herzen reden*.", footnotes: ["℘ Hes 20,35", "℘ 1Mo 34,3; Ri 19,3; Rt 2,13; Jes 40,2"] },
      { number: 17, text: "Dann gebe ich ihr von dort aus ihre Weinberge und das Tal Achor* als Tor der Hoffnung. Und dort wird sie willig sein* wie in den Tagen ihrer Jugend und wie an dem Tag, als sie aus dem Land Ägypten heraufzog*.", footnotes: ["℘ Jos 7,26", "w. dort wird sie antworten, o. dort wird sie mein Werben erhören, o. dort wird sie singen", "℘ 2Mo 15,1; Jer 2,2"] },
      { number: 18, text: "Und es wird geschehen an jenem Tag, spricht der HERR*, da rufst du: Mein Mann*! Und du rufst mich nicht mehr: Mein Baal!", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Jes 54,5"] },
      { number: 19, text: "Und ich entferne die Namen der Baalim aus ihrem Mund, und sie werden nicht mehr mit ihrem Namen erwähnt*.", footnotes: ["℘ Kap. 14,4; Sach 13,2"] },
      { number: 20, text: "Und ich schließe für sie an jenem Tag einen Bund mit den Tieren des Feldes* und mit den Vögeln des Himmels und mit den kriechenden Tieren des Erdbodens*. Und Bogen und Schwert und Krieg zerbreche ich* und entferne sie aus dem Land. Und ich lasse sie in Sicherheit wohnen*.", footnotes: ["℘ Hes 16,62; 34,25", "℘ 1Mo 9,10", "℘ Jes 2,4; Mi 4,3; Sach 9,10", "℘ 3Mo 26,5.6; Jer 30,10"] },
      { number: 21, text: "Und ich will dich mir verloben* in Ewigkeit, und ich will dich mir verloben* in Gerechtigkeit und in Recht und in Gnade und in Erbarmen,", footnotes: ["d. i. ein öffentlicher Rechtsakt, der durch Zahlung des Brautpreises das Mädchen rechtlich zur Ehefrau bestimmt", "d. i. ein öffentlicher Rechtsakt, der durch Zahlung des Brautpreises das Mädchen rechtlich zur Ehefrau bestimmt"] },
      { number: 22, text: "ja in Treue* will ich dich mir verloben*; und du wirst den HERRN erkennen.", footnotes: ["o. Wahrheit", "d. i. ein öffentlicher Rechtsakt, der durch Zahlung des Brautpreises das Mädchen rechtlich zur Ehefrau bestimmt\n℘ Jes 62,4.5; Jer 24,7; Sach 8,8; 2Kor 11,2"] },
      { number: 23, text: "Und es wird geschehen an jenem Tag, da werde ich erhören, spricht der HERR*. Ich erhöre den Himmel, und der erhört die Erde;", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 24, text: "und die Erde erhört das Korn und den Most und das Öl*, und diese erhören Jesreel*.", footnotes: ["℘ Ps 67,7; Jer 31,12; Hes 36,29; Am 9,13", "d. h. Gott sät"] },
      { number: 25, text: "Und ich will sie* mir säen im Land* und will mich über die Lo-Ruhama* erbarmen*. Und ich will zu Lo-Ammi* sagen: Du bist mein Volk*! Und er* wird sagen: Mein Gott!*", footnotes: ["d. i. die Frau; vgl. Kap. 2,4—17", "℘ Jer 31,27; Sach 10,9", "℘ Kap. 1,6", "℘ 1Petr 2,10", "℘ Kap. 1,9", "℘ Jes 51,16; Röm 9,25", "d. i. Lo-Ammi; o. Und es; d. i. das Volk", "℘ V. 1; Jer 30,22; Sach 13,9"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und der HERR sprach zu mir: Geh noch einmal, liebe eine Frau, die sich von einem anderen* lieben lässt und Ehebruch treibt*, wie der HERR die Söhne Israel liebt, die sich aber anderen Göttern zuwenden und Traubenkuchen lieben.", heading: "Zeichenhandlung: Hosea heiratet seine hurerische Frau ein zweites Mal", footnotes: ["o. kollektiv: von Freunden", "℘ Kap. 1,2"] },
      { number: 2, text: "Da kaufte ich sie mir für fünfzehn Silberschekel und einen Homer Gerste und einen Letech Gerste." },
      { number: 3, text: "Und ich sagte zu ihr: Viele Tage sollst du bei mir bleiben, du sollst nicht huren und keinem Mann gehören; und auch ich verhalte mich dir gegenüber so." },
      { number: 4, text: "Denn die Söhne Israel bleiben viele Tage ohne König und ohne Oberste*, ohne Schlachtopfer und ohne Gedenkstein und ohne Efod* und Terafim*.", footnotes: ["℘ Kap. 10,3; Kla 2,9; Hes 19,14", "℘ 2Mo 28,6; Ri 8,27", "℘ Ri 17,5; Hes 21,31"] },
      { number: 5, text: "Danach werden die Söhne Israel umkehren und den HERRN, ihren Gott*, aufsuchen und David, ihren König*. Und sie werden sich bebend zum HERRN wenden* und zu seiner Güte am Ende der Tage*.", footnotes: ["℘ Kap. 5,15; 6,1; Jer 50,4.5", "℘ Jer 30,9; Hes 37,24", "℘ Jes 60,5", "℘ Jer 3,22; Dan 10,14"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Hört das Wort des HERRN, ihr Söhne Israel!* Denn der HERR hat einen Rechtsstreit mit den Bewohnern des Landes*; denn keine Treue und keine Gnade* und keine Erkenntnis Gottes ist im Land*.", heading: "Anklagen gegen Israel wegen Götzendienstes — Warnung an Juda", footnotes: ["℘ Kap. 5,1; Ps 81,9", "℘ Kap. 12,3", "o. denn keine Wahrheit und keine Liebe", "℘ Kap. 5,4; Jer 4,22; 9,7"] },
      { number: 2, text: "Verfluchen und Lügen, Morden, Stehlen und Ehebrechen haben sich ausgebreitet*, und Bluttat* reiht sich an Bluttat*.", footnotes: ["w. haben alle Schranken durchbrochen\n℘ Jer 5,2.7", "o. Blutschuld", "℘ Kap. 12,15"] },
      { number: 3, text: "Darum vertrocknet das Land und welkt jeder*, der darin wohnt*, samt den Tieren des Feldes und den Vögeln des Himmels*; selbst die Fische des Meeres werden dahingerafft*.", footnotes: ["o. Darum trauert das Land und wird jeder hinfällig", "℘ Jes 24,4.6; Jer 4,28; Am 5,16", "℘ Jer 9,9", "℘ Zef 1,3"] },
      { number: 4, text: "Jedoch niemand soll rechten oder jemanden zurechtweisen*! Sondern mit dir führe ich den Rechtsstreit, Priester*,", footnotes: ["℘ Am 5,13", "T.; Mas. T.: Aber dein Volk ist wie die, die mit dem Priester den Rechtsstreit führen\n℘ 5Mo 17,12"] },
      { number: 5, text: "so dass du stürzt am hellen Tag. Ja, auch der Prophet stürzt mit dir bei Nacht*. Und ich lasse deine Mutter umkommen*.", footnotes: ["Manche lesen mit Textänderung: Kam doch auch durch deine Schuld mein Volk zu Fall wie bei Nacht.\n℘ Jer 6,15; Mi 3,5-7", "℘ Jes 50,1"] },
      { number: 6, text: "Mein Volk kommt um aus Mangel an Erkenntnis*. Weil du die Erkenntnis verworfen hast, so verwerfe ich dich, dass du mir nicht mehr als Priester dienst*. Du hast das Gesetz deines Gottes vergessen*, so vergesse auch ich deine Kinder.", footnotes: ["℘ Kap. 8,12", "℘ Kap. 9,17", "℘ Ps 18,27"] },
      { number: 7, text: "Je mehr sie wurden, desto mehr sündigten sie gegen mich*. Ihre Ehre vertausche ich gegen Schande.", footnotes: ["℘ 5Mo 32,15"] },
      { number: 8, text: "Die Sünde* meines Volkes essen sie*, und nach ihrer Schuld verlangen sie*.", footnotes: ["o. Das Sündopfer", "℘ 3Mo 6,22", "w. erheben sich ihre Seelen"] },
      { number: 9, text: "Und wie dem Volk, so wird es dem Priester ergehen*. Und ich suche seine Wege an ihm heim, und seine Taten vergelte ich ihm*.", footnotes: ["℘ Jes 24,2", "℘ Kap. 12,3; Spr 11,31"] },
      { number: 10, text: "Sie essen, aber werden nicht satt werden*. Sie treiben Hurerei*, doch sie werden sich nicht ausbreiten. *Denn sie haben es aufgegeben, auf den HERRN zu achten*.", footnotes: ["℘ Hag 1,6", "o. halten zur Hurerei an", "o. Ja, sie haben den HERRN verlassen, um auf Hurerei zu achten.", "℘ Jer 9,12"] },
      { number: 11, text: "Hurerei,* Wein und Most nehmen den Verstand weg*.", footnotes: ["o. Ja, sie haben den HERRN verlassen, um auf Hurerei zu achten.", "℘ Kap. 7,11; Spr 6,32; 20,1; Jes 28,7"] },
      { number: 12, text: "Mein Volk befragt sein Holz, und sein Stab gibt ihm Auskunft*. Denn der Geist der Hurerei hat es irregeführt*, und sie huren von ihrem Gott weg*.", footnotes: ["℘ Hes 20,32", "℘ Jes 44,20; Jer 23,13", "℘ Kap. 5,4; 6,10; 9,1"] },
      { number: 13, text: "Auf den Gipfeln der Berge opfern sie*, und auf den Hügeln bringen sie Rauchopfer dar, unter Eiche und Storaxbaum und Terebinthe, weil ihr Schatten gut ist*. Darum huren eure Töchter, und eure Schwiegertöchter treiben Ehebruch.", footnotes: ["o. halten sie Opfermahlzeiten; w. schlachten sie zum Opfer", "℘ 2Kö 17,7"] },
      { number: 14, text: "Nicht an euren Töchtern suche ich es heim, dass sie huren, und nicht an euren Schwiegertöchtern, dass sie Ehebruch treiben. Denn sie selbst* gehen mit den Huren beiseite, und abseits mit den Tempeldirnen opfern sie*. So kommt das Volk, das keine Einsicht hat, zu Fall*.", footnotes: ["d. h. ihre Väter (V. 13); o. die Priester (V. 9)", "o. halten sie Opfermahlzeiten; w. schlachten sie zum Opfer\n℘ 2Kö 23,7", "℘ Jes 27,11"] },
      { number: 15, text: "Wenn du hurst, Israel, soll Juda nicht schuldig werden*. Kommt nicht nach Gilgal* und zieht nicht hinauf nach Bet-Awen*! Und schwört nicht: So wahr der HERR lebt!*", footnotes: ["℘ Kap. 12,1-3; 2Chr 21,11", "℘ Kap. 9,15; 12,12; Jos 5,9", "d. h. Götzenhaus; ironische Bezeichnung für Bethel (Gotteshaus)\n℘ Kap. 5,8; 10,5; Jos 7,2", "℘ Zef 1,5"] },
      { number: 16, text: "Ja, Israel ist widerspenstig geworden wie eine widerspenstige Kuh*. Wird da der HERR sie weiden wie ein Lamm auf weitem Raum?", footnotes: ["℘ Jer 31,18"] },
      { number: 17, text: "Verbündet mit Götzenbildern ist Ephraim*. Lass es gewähren!", footnotes: ["℘ Kap. 11,2"] },
      { number: 18, text: "Ist ihr Zechen vorbei, huren*, ja huren sie*. Sie lieben und lieben*; die Gegengabe dafür ist Schande*.", footnotes: ["℘ Hes 16,15", "o. halten zur Hurerei an", "T.; andere üs.: Sie lieben das »Her damit!«", "Andere üs. die zweite Vershälfte mit Textänderung: Sie lieben leidenschaftlich die Schande ihrer Schamlosigkeit"] },
      { number: 19, text: "Ein Wind wickelt sie* ein in seine Flügel*, und sie werden zuschanden mit ihren Altären*.", footnotes: ["Viell. ist Ephraim als Frau gemeint.", "℘ Kap. 13,15; Jer 4,11.12", "w. ihre Altäre werden zuschanden\n℘ Kap. 10,5.6; Jes 1,29"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Hört dies, ihr Priester, und merkt auf, Haus Israel!* Und ihr, Haus des Königs, nehmt es zu Ohren! Denn euch gilt das Urteil*. Ja, ihr seid eine Falle für Mizpa* und ein ausgespanntes Fangnetz auf dem Tabor*;", heading: "Gerichtsworte über die Priester und das Königshaus von Israel", footnotes: ["℘ Kap. 4,1; Jer 11,7; Joe 1,2; Am 3,1", "o. an euch ist es, das Recht zu wahren o. zu sprechen", "℘ 1Sam 7,5", "℘ Ri 4,6"] },
      { number: 2, text: "und die Abtrünnigen haben die Unzucht weit getrieben*. Ich aber bin eine Züchtigung für sie alle.", footnotes: ["w. tief gemacht. — Mit Textänderung üs. andere: und eine Fanggrube zu Schittim, die man tief grub\n℘ Kap. 6,9"] },
      { number: 3, text: "Ich selbst habe Ephraim erkannt, und Israel ist nicht vor mir verborgen*. Denn nun hast du Hurerei getrieben, Ephraim; Israel hat sich unrein gemacht*.", footnotes: ["℘ Kap. 13,5", "o. Denn als du zur Hurerei anhieltest, Ephraim, hat Israel sich verunreinigt\n℘ Kap. 1,2"] },
      { number: 4, text: "Ihre Taten gestatten ihnen nicht, zu ihrem Gott umzukehren. Denn der Geist der Hurerei ist in ihrem Innern*, und den HERRN erkennen sie nicht*.", footnotes: ["℘ Kap. 4,11.12", "℘ Kap. 4,1; 8,11"] },
      { number: 5, text: "Der Hochmut Israels zeugt ihm ins Angesicht*, und Israel und Ephraim werden stürzen über ihre Schuld*; auch Juda stürzt mit ihnen*.", footnotes: ["℘ Kap. 7,10", "℘ Kap. 14,2; Spr 11,5", "℘ Jes 3,8.9"] },
      { number: 6, text: "Mit ihren Schafen und mit ihren Rindern werden sie hingehen, um den HERRN zu suchen, und werden ihn nicht finden*; er hat sich ihnen entzogen*.", footnotes: ["℘ Spr 1,28; Am 8,12", "℘ Kap. 8,13"] },
      { number: 7, text: "Sie haben treulos gegen den HERRN gehandelt*, denn sie haben fremde Kinder gezeugt. Nun wird sie ein Neumond* verzehren mit ihren Grundstücken*.", footnotes: ["℘ Kap. 6,7; 7,13", "o. ein Monat", "w. mit ihren Anteilen am Land"] },
      { number: 8, text: "Stoßt ins Horn zu Gibea*, in die Trompete zu Rama*! Erhebt Kriegsgeschrei in Bet-Awen*: Der Feind ist hinter dir her, Benjamin!", heading: "Zwiegespräch Gottes mit seinem Volk: Bruderkrieg als Gerichtsandrohung, flüchtige Umkehr des Volkes, Gottes Klage", footnotes: ["℘ Kap. 8,1; Ri 19,13", "℘ 2Kö 17,7", "℘ Kap. 4,15"] },
      { number: 9, text: "Ephraim wird zur Wüste werden am Tag der Züchtigung*. Über die Stämme Israels habe ich Zuverlässiges verkündet*.", footnotes: ["℘ Kap. 9,7; Mi 6,13", "℘ Kap. 7,12"] },
      { number: 10, text: "Die Obersten von Juda sind geworden wie solche, die die Grenze verrücken*. Über sie schütte ich meinen Grimm aus wie Wasser*.", footnotes: ["℘ 5Mo 27,17", "℘ Ps 88,17.18"] },
      { number: 11, text: "Unterdrückt ist Ephraim, zerbrochen das Recht*; denn eilfertig lief es den nichtigen Götzen nach*.", footnotes: ["o. misshandelt im Gericht", "so mit LXX; Mas. T. ist unsicher; viell.: lief es menschlicher Anordnung nach"] },
      { number: 12, text: "Und ich bin wie Eiter* für Ephraim und wie Fäulnis* für das Haus Juda.", footnotes: ["o. wie eine Motte", "o. Wurmfraß"] },
      { number: 13, text: "Ephraim sah seine Krankheit und Juda sein Geschwür. Da ging Ephraim nach Assur* und sandte hin zum König Jareb*. Der aber kann euch nicht gesund machen und wird euch von eurem Geschwür nicht heilen.", footnotes: ["℘ Kap. 7,11; 8,9; 2Kö 15,19; 2Chr 28,16.20.21; Hes 23,5", "d. h. Streiter, o. Streitsüchtiger\n℘ Kap. 10,6"] },
      { number: 14, text: "Denn ich bin wie ein Löwe für Ephraim* und wie ein Junglöwe für das Haus Juda. Ich, ich zerreiße und gehe davon; ich trage weg, und niemand rettet*.", footnotes: ["℘ Kap. 13,6-8; Kla 3,10", "℘ Kap. 2,12; 5Mo 32,39"] },
      { number: 15, text: "Ich gehe, kehre zurück an meinen Ort, bis sie ihre Schuld büßen und mein Angesicht suchen. In ihrer Not werden sie mich suchen*.", footnotes: ["℘ Kap. 3,5; Ri 6,6; Ps 107,6; Jes 26,16"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "»Kommt und lasst uns zum HERRN umkehren*! Denn er hat zerrissen, er wird uns auch heilen; er hat geschlagen, er wird uns auch verbinden*.", footnotes: ["℘ Kap. 3,5; 2Chr 30,6", "℘ Hi 5,18; 22,23"] },
      { number: 2, text: "Er wird uns nach zwei Tagen neu beleben, am dritten Tag uns aufrichten*, dass wir vor seinem Angesicht leben*.", footnotes: ["℘ Jes 26,19", "℘ Kap. 7,2; Lk 1,75"] },
      { number: 3, text: "So lasst uns ihn erkennen*, ja, lasst uns nachjagen der Erkenntnis des HERRN! Sicher wie die Morgenröte ist sein Hervortreten. Er kommt wie der Regen zu uns, wie der Spätregen, der die Erde benetzt*.«", footnotes: ["℘ Phil 3,8", "℘ Kap. 10,12; 14,6; Ps 72,6"] },
      { number: 4, text: "Was soll ich dir tun, Ephraim*? Was soll ich dir tun, Juda, da eure Güte* wie die Morgenwolke ist und wie der Tau, der früh verschwindet*?", footnotes: ["℘ Kap. 11,8", "o. Gnade; o. Liebe; o. Bundestreue", "℘ Kap. 13,3; Ri 3,12"] },
      { number: 5, text: "Darum habe ich durch die Propheten dreingeschlagen*, habe sie erschlagen durch die Worte meines Mundes*; und mein Recht geht hervor wie das Licht*.", footnotes: ["w. gespalten, o. ausgehauen\n℘ Jer 1,10", "℘ Jes 11,4; Jer 5,14", "so mit LXX, der syr. und aram. Üs.; Mas. T.: und deine Rechte (o. Gerichte) sind Licht, das hervortritt\n℘ Zef 3,5"] },
      { number: 6, text: "Denn an Güte* habe ich Gefallen, nicht an Schlachtopfern*, und an der Erkenntnis Gottes mehr als an Brandopfern*.", footnotes: ["o. Gnade; o. Liebe; o. Bundestreue", "℘ 1Sam 15,22; Mt 9,13", "℘ Kap. 8,13; Mi 6,8"] },
      { number: 7, text: "Sie aber haben den Bund übertreten* wie die Bewohner von Adam*, haben dort* treulos gegen mich gehandelt*.", heading: "Bundesbruch und Verwilderung in Israel — von Gott aufgedeckt", footnotes: ["℘ Jes 24,5", "zur Ortschaft »Adam« vgl. Jos 3,16", "o. haben den Bund übertreten wie Adam, haben damals", "℘ Kap. 5,7; 8,1; 5Mo 31,20"] },
      { number: 8, text: "Gilead ist eine Stadt von Übeltätern*, voll Blutspuren.", footnotes: ["℘ Kap. 12,12"] },
      { number: 9, text: "Und wie Räuber im Hinterhalt warten, so die Rotte der Priester. Sie morden auf dem Weg nach Sichem*, ja, sie verüben Schandtat*.", footnotes: ["℘ 1Mo 12,6", "℘ Kap. 5,1.2; Mi 7,2"] },
      { number: 10, text: "Im Haus Israel habe ich Abscheuliches gesehen: Da ist Ephraims Hurerei, da hat Israel sich unrein gemacht*.", footnotes: ["℘ Kap. 4,12.17; Jer 5,30"] },
      { number: 11, text: "Auch dir, Juda, *ist eine Ernte bestimmt! Wenn ich das Geschick* meines Volkes wende*,", footnotes: ["o. ist eine Ernte bestimmt, wenn ich das Geschick meines Volkes wende, 1 wenn ich Israel heile. Ja, aufgedeckt sind die Schuld Ephraims und die Bosheiten Samarias: Man übt", "o. die Wegführung in die Gefangenschaft", "℘ Joe 4,1"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "wenn ich Israel heile, werden die Schuld Ephraims und die Bosheiten Samarias aufgedeckt*. Denn sie üben* Betrug*, der Dieb dringt ein, die Räuberbande plündert draußen.", footnotes: ["℘ Am 3,9-11", "o. ist eine Ernte bestimmt, wenn ich das Geschick meines Volkes wende, 1 wenn ich Israel heile. Ja, aufgedeckt sind die Schuld Ephraims und die Bosheiten Samarias: Man übt", "℘ Kap. 12,1; Jes 59,13.14"] },
      { number: 2, text: "Aber sie bedenken nicht in ihrem Herzen, dass ich mich an all ihre Bosheit erinnere*. Nun haben ihre Taten sie umringt, sie sind vor meinem Angesicht*.", footnotes: ["℘ Ps 10,11; Jer 14,10; Hes 21,29", "℘ Kap. 6,2; Spr 5,21"] },
      { number: 3, text: "Mit ihrer Bosheit erfreuen sie den König und mit ihren Lügen die Obersten." },
      { number: 4, text: "Sie alle sind Ehebrecher* wie ein brennender Ofen ohne Bäcker. Der hört auf zu schüren vom Kneten des Teiges an bis zu seiner Säuerung.", footnotes: ["℘ Jer 5,7; 9,1"] },
      { number: 5, text: "Am Tag unsres* Königs machen sie* die Obersten krank von der Glut des Weines*. Seine Gewalt reißt die Schwätzer davon.", footnotes: ["aram. Üs.: ihres", "o. sich", "℘ Jes 28,7"] },
      { number: 6, text: "Denn sie nähern sich* mit Hinterlist*, während ihr Herz wie ein Ofen ist*: Ihr Zorn* schläft die ganze Nacht; am Morgen brennt er wie ein flammendes Feuer*.", footnotes: ["so mit anderer Vokalisierung in Anlehnung an die griech. Üs.; Mas. T.: Denn sie bringen ihn; viell. den Wein; vgl. V. 5", "w. in ihrem Hinterhalt", "Andere üs. mit LXX: Ja, erhitzt wie ein Ofen ist ihr Herz in ihrem Hinterhalt.", "so mit der syr. und aram. Üs.; Mas. T.: Bäcker", "℘ Mi 2,1"] },
      { number: 7, text: "Sie alle glühen wie ein Ofen, sie verzehren ihre Richter. Alle ihre Könige fallen*, keiner von ihnen ruft mich an*.", footnotes: ["℘ 2Kö 15,10", "℘ Ps 14,4; Jes 64,4"] },
      { number: 8, text: "Ephraim vermischt sich* mit den Völkern*. Ephraim ist ein Brotfladen geworden, der nicht gewendet ist.", footnotes: ["w. wird hin- und hergeschüttelt, o. lässt sich verrühren", "℘ Ps 106,35"] },
      { number: 9, text: "Fremde verzehren seine Kraft, und er erkennt es nicht. Auch graues Haar hat sich bei ihm eingeschlichen, und er erkennt es nicht." },
      { number: 10, text: "So zeugt der Hochmut Israels ihm selbst ins Gesicht*. Und sie kehren nicht um zum HERRN, ihrem Gott, und bei alledem suchen sie ihn nicht*.", footnotes: ["℘ Kap. 5,5", "℘ Kap. 13,14; Jes 9,12; Zef 1,6"] },
      { number: 11, text: "Und Ephraim ist wie eine Taube geworden, die sich betören lässt, ohne Verstand*. Ägypten rufen sie an, nach Assur laufen sie*.", footnotes: ["℘ Kap. 4,11; Ob 7", "℘ Kap. 5,13; 12,2; 2Kö 16,7; Jer 2,36"] },
      { number: 12, text: "Sowie sie hinlaufen, spanne ich mein Fangnetz über sie aus; wie Vögel des Himmels hole ich sie herunter*. Ich züchtige sie, wie es ihrer Gemeinde verkündigt worden ist*.", footnotes: ["℘ Pred 9,12; Hes 12,13", "℘ Kap. 5,9; 5Mo 28,15"] },
      { number: 13, text: "Wehe ihnen! Denn sie sind vor mir geflohen*. Verwüstung über sie! Denn sie haben mit mir gebrochen*. Und ich, ich wollte sie wohl loskaufen, sie aber reden Lügen über mich.*", footnotes: ["℘ Jes 30,1.2", "o. sind von mir abgefallen\n℘ Kap. 5,7", "o. Und ich, sollte ich sie loskaufen, während sie Lügen über mich reden?"] },
      { number: 14, text: "Und sie schreien in ihrem Herzen nicht zu mir* um Hilfe, sondern heulen auf ihren Lagern, ritzen* sich wegen Korn und Most* und wenden sich gegen mich*.", footnotes: ["℘ Jes 29,13; Jer 3,10; 12,2", "o. wenn sie auf ihren Lagern heulen, ritzen sie", "so mit mehreren hebr. Handschr.; Mas. T.: treiben sich wegen Korn und Most umher", "w. weichen ab gegen mich; andere lesen mit der syr. und aram. Üs.: sind widerspenstig gegen mich\n℘ Kap. 13,9"] },
      { number: 15, text: "Und ich, ich wies sie zurecht, ich stärkte ihre Arme, doch sie ersinnen Böses gegen mich." },
      { number: 16, text: "Sie wenden sich um, doch nicht zu mir*. Sie sind wie ein schlaffer* Bogen geworden*. Ihre Obersten werden durchs Schwert fallen wegen der Verwünschung ihrer Zunge*; das wird ihre Verspottung sein im Land Ägypten*.", footnotes: ["so mit Ergänzung eines Buchstabens; Mas. T.: nicht oben\n℘ Kap. 11,7", "o. trügerischer", "℘ Ps 78,57", "℘ Ps 12,5", "o. wegen des Stammelns ihrer Zunge — das ist ihr Stottern — im Land Ägypten\n℘ Kap. 9,3.6; Jer 42,18"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "An deinen Mund das Horn!* Wie ein Adler kommt es über das Haus des HERRN*, weil sie meinen Bund übertreten und mit meinem Gesetz gebrochen haben*.", heading: "Gerichtsandrohung für Israels Abkehr von seinem Gott", footnotes: ["℘ Kap. 5,8; Jer 4,5", "℘ 5Mo 28,49", "o. von meinem Gesetz abgefallen sind\n℘ Kap. 6,7"] },
      { number: 2, text: "Sie schreien zu mir um Hilfe: Mein Gott, wir kennen dich, wir, Israel*!", footnotes: ["℘ Mt 7,22; Tit 1,16"] },
      { number: 3, text: "Doch Israel hat das Gute verworfen; der Feind jage ihm nach!" },
      { number: 4, text: "Sie selbst haben Könige gemacht, doch es ging nicht von mir aus. Sie haben Oberste eingesetzt, und ich wusste es nicht*. Ihr Silber und ihr Gold verwendeten sie für ihre Götzenbilder*, damit es vernichtet wird.", footnotes: ["℘ 2Kö 15,10", "℘ Kap. 13,2"] },
      { number: 5, text: "Er hat dein Kalb verworfen, Samaria*. Mein Zorn ist gegen sie entbrannt. Wie lange sind sie zur Reinheit unfähig?*", footnotes: ["℘ Kap. 10,5-8; 2Chr 13,8; Mi 1,7", "o. Bis wann? Sie können doch nicht ungestraft bleiben.\n℘ Jer 13,27"] },
      { number: 6, text: "Denn es ist von Israel — das hat ein Handwerker gemacht, kein Gott ist das*. Vielmehr wird das Kalb Samarias zu Stücken werden*.", footnotes: ["℘ Jer 10,3-11", "℘ Kap. 10,5-8; 2Chr 13,8; Mi 1,7"] },
      { number: 7, text: "Ja, Wind säen sie, und Sturm ernten sie*. Ein Halm, der nicht sprosst, bringt kein Mehl*. Selbst wenn er etwas brächte, würden Fremde es verschlingen*.", footnotes: ["℘ Kap. 10,13; Spr 22,8", "℘ Jer 12,13", "℘ 5Mo 28,33"] },
      { number: 8, text: "Verschlungen ist Israel. Jetzt sind sie unter den Nationen wie ein Gefäß geworden, an dem man kein Gefallen hat*.", footnotes: ["℘ Jer 22,28; Kla 4,2"] },
      { number: 9, text: "Denn sie, sie sind nach Assur hinaufgezogen*. Ein Wildesel bleibt für sich allein*, Ephraim aber spendet Liebesgeschenke*.", footnotes: ["℘ Kap. 5,13", "℘ Hi 39,5", "℘ Kap. 12,2; Jes 30,2.6; Hes 16,33"] },
      { number: 10, text: "Auch wenn sie unter den Nationen Liebesgeschenke annehmen*, will ich sie jetzt sammeln*, dass sie sich bald winden* wegen der Last des Königs der Fürsten*.", footnotes: ["℘ Kap. 12,2; Jes 30,2.6; Hes 16,33", "o. zusammentreiben. — Andere stellen zwei Buchstaben um und üs.: ich werde sie abhacken", "so mit Vokaländerung; Mas. T.: dass sie anfangen, wenig zu sein", "d. h. des Königs von Assur\n℘ 2Kö 17,3.4; Jes 10,8"] },
      { number: 11, text: "Ja, Ephraim hat die Altäre vermehrt, zum Sündigen dienen sie ihm, Altäre zum Sündigen*.", footnotes: ["℘ Kap. 5,4; 10,1; Jer 17,1"] },
      { number: 12, text: "Schriebe ich ihm zehntausendfach meine Gesetze auf*, wie Fremdes würden sie geachtet*.", footnotes: ["℘ Ps 147,19.20", "℘ Kap. 4,6"] },
      { number: 13, text: "Als Schlachtopfer meiner Opfergaben opfern sie Fleisch und essen es*. Der HERR hat kein Gefallen daran*. Jetzt denkt er an ihre Schuld und sucht ihre Sünden heim*. Nach Ägypten werden sie zurückkehren*.", footnotes: ["℘ Jer 7,21", "℘ Kap. 5,6; 6,6; Jes 1,11", "℘ Kap. 9,9; 2Mo 32,34", "℘ Kap. 9,3.6; 5Mo 28,68"] },
      { number: 14, text: "Israel hat den vergessen, der es machte*, und hat Paläste gebaut; und Juda hat die befestigten Städte vermehrt. Aber ich werfe Feuer in seine Städte, das verzehrt seine Paläste*.", footnotes: ["℘ Kap. 13,6; 5Mo 32,18; Jes 17,10; Jer 3,21", "℘ Am 2,5"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Freue dich nicht, Israel, bis zum Jubel wie die Völker! Denn du hurst weg von deinem Gott*, du liebst Dirnenlohn auf allen Korntennen.", heading: "Das Ende des unbeschwerten Lebens für Israel", footnotes: ["℘ Kap. 4,12; Jer 2,19; Hes 16,15.30"] },
      { number: 2, text: "Tenne und Kelterkufe werden sie nicht ernähren*, und der Most wird sie im Stich lassen*.", footnotes: ["w. weiden", "℘ Kap. 2,11; Am 5,11"] },
      { number: 3, text: "Sie werden nicht im Land des HERRN* bleiben*, Ephraim wird nach Ägypten zurückkehren*, in Assur werden sie Unreines essen*.", footnotes: ["℘ 3Mo 25,23", "℘ 1Kö 9,7", "℘ Kap. 7,16; 8,13", "℘ Kap. 11,5; 2Kö 17,6; Hes 4,13; Dan 1,8"] },
      { number: 4, text: "Sie werden dem HERRN keinen Wein spenden und ihm ihre Schlachtopfer nicht darbringen*. Wie Trauerbrot wird es für sie sein*: Alle, die davon essen, werden sich unrein machen. Denn für ihre Kehle* wird ihr Brot sein, in das Haus des HERRN wird es nicht kommen*.", footnotes: ["o. und ihre Schlachtopfer werden ihm nicht wohlgefällig sein", "℘ Kap. 7,16; 8,13", "o. Seele", "℘ 5Mo 26,14"] },
      { number: 5, text: "Was werdet ihr tun am Tag der Festversammlung und am Tag des Festes des HERRN?" },
      { number: 6, text: "Denn siehe, nachdem sie wegen der Verwüstung weggezogen sind*, wird Ägypten sie sammeln, Memfis* wird sie begraben*. Kostbar ist ihr Silber — Nesseln werden sie beerben, Dornen werden in ihren Zelten sein*.", footnotes: ["℘ 3Mo 26,33", "℘ Jes 19,13", "℘ Jer 2,16; 42,22; 44,12", "℘ Jes 32,13"] },
      { number: 7, text: "Gekommen sind die Tage der Heimsuchung, gekommen die Tage der Vergeltung*; Israel wird es erkennen. »Ein Narr ist der Prophet, verrückt der Mann des Geistes.« Wegen der Größe deiner Schuld ist auch die Anfeindung groß.", footnotes: ["℘ Kap. 5,9; Am 8,2; Mi 7,4; Lk 21,22"] },
      { number: 8, text: "Der Wächter Ephraims, nämlich der Prophet, ist neben meinem Gott. Die Falle eines Vogelstellers ist auf all seinen Wegen*, Anfeindung ist im Haus seines Gottes.", footnotes: ["℘ Jer 11,19"] },
      { number: 9, text: "Sie haben zutiefst verdorben gehandelt* wie in den Tagen von Gibea*. Er wird an ihre Schuld denken, er wird ihre Sünden heimsuchen*.", footnotes: ["℘ 2Mo 32,7", "℘ Kap. 10,9; Ri 19,22-27", "℘ Kap. 8,13; Hes 21,28"] },
      { number: 10, text: "Wie Trauben in der Wüste fand ich Israel*, wie eine Frühfrucht am Feigenbaum, als seinen ersten Trieb* sah ich eure Väter*. Sie aber gingen nach* Baal-Peor* und weihten sich der Schande* und sie wurden Scheusale wie ihr Liebhaber*.", heading: "Sünde von Anfang an — am Ende: verdorrte Kraft", footnotes: ["℘ Kap. 13,5; Jer 2,2", "w. in seinem Anfang der Reife", "℘ Jer 24,2", "o. zum", "℘ 4Mo 25,1-3; Ps 106,28", "d. h. dem Schandgott Baal\n℘ Jer 3,24", "w. ihrem Lieben entsprechend\n℘ 2Kö 17,11"] },
      { number: 11, text: "Ephraim ist den Vögeln gleich, seine Herrlichkeit verfliegt*. Kein Gebären, keine Schwangerschaft*, keine Empfängnis*.", footnotes: ["o. ihre Menge zerstiebt", "w. kein Mutterleib", "℘ 5Mo 28,18"] },
      { number: 12, text: "Selbst wenn sie ihre Söhne großziehen sollten, mache ich sie doch kinderlos, so dass kein Mensch mehr bleibt*. Ja, wehe auch ihnen selbst, wenn ich von ihnen weiche!*", footnotes: ["℘ 5Mo 32,25", "℘ 4Mo 14,34"] },
      { number: 13, text: "Ephraim, das ich mir zur jungen Palme ausersehen hatte, auf einer Weide gepflanzt, Ephraim muss seine Söhne zum Mörder hinausziehen lassen*.", footnotes: ["℘ Kap. 14,1; Hi 27,14; Kla 2,22"] },
      { number: 14, text: "Gib ihnen, HERR! Was wirst du geben?* Gib ihnen einen unfruchtbaren Mutterleib und vertrocknete Brüste*!", footnotes: ["o. . . ., was du geben willst!", "℘ 5Mo 28,18"] },
      { number: 15, text: "Ihre ganze Bosheit wurde in Gilgal offenkundig*, ja, dort habe ich sie gehasst. Wegen der Bosheit ihrer Taten vertreibe ich sie aus meinem Haus. Ich werde sie nicht mehr lieben*; all ihre Obersten sind Widerspenstige*.", footnotes: ["℘ Kap. 4,15; Am 4,4", "℘ Jer 15,1.2", "℘ Jes 1,23"] },
      { number: 16, text: "Geschlagen ist Ephraim, verdorrt ihre Wurzel*, Frucht bringen sie nicht mehr. Selbst wenn sie gebären, werde ich die Lieblinge ihres Leibes töten*.", footnotes: ["℘ Mt 21,19", "℘ 5Mo 32,25"] },
      { number: 17, text: "Mein Gott verwirft sie*, weil sie nicht auf ihn hören*; und sie sollen Flüchtlinge sein unter den Nationen*.", footnotes: ["o. soll sie verwerfen", "℘ Ps 81,12; Jer 7,13.15", "℘ Kap. 4,6; 5Mo 4,25-27; 1Kö 14,16; Sach 7,14"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Israel war ein üppiger Weinstock, der genügend Frucht hatte*. Je zahlreicher seine Frucht wurde, desto zahlreicher machte er die Altäre*. Je schöner sein Land wurde, desto schöner machten sie die Gedenksteine*.", heading: "Gerichtsankündigung über Israel wegen seines Götzendienstes", footnotes: ["℘ Jes 5,4.7", "℘ Kap. 8,11; 13,2; Jer 11,13.17", "hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden\n℘ Kap. 2,10"] },
      { number: 2, text: "Geteilt* ist ihr Herz, jetzt werden sie büßen: Er zerbricht ihre Altäre, verwüstet ihre Gedenksteine*.", footnotes: ["o. Glatt; o. Gleißnerisch", "hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden\n℘ 2Mo 23,24; 3Mo 26,30"] },
      { number: 3, text: "Ja, jetzt werden sie sagen: Wir haben keinen König*. Denn wir haben den HERRN nicht gefürchtet, und der König, was soll er für uns tun*?", footnotes: ["℘ Kap. 3,4; 13,10; 2Kö 15,13", "o. was tat er für uns\n℘ Ps 118,9"] },
      { number: 4, text: "Sie haben viele Worte geredet, Meineide geschworen*, Bündnisse geschlossen*: So sprosst der Rechtsspruch wie Giftkraut* in den Furchen des Feldes.", footnotes: ["o. zu Unrecht Verfluchung ausgesprochen", "℘ 2Kö 17,3.4", "o. das Recht wie Bitterkraut"] },
      { number: 5, text: "Die Bewohner von Samaria bangen um das Kalb* von Bet-Awen*; ja, sein Volk* wird noch trauern darüber. Seine Götzenpriester heulen um es wegen seiner Herrlichkeit, denn* sie wird gefangen von ihm wegziehen*.", footnotes: ["d. i. eine verächtliche Ausdrucksweise; etwa: Kälberzeug", "℘ Kap. 4,15", "o. verehren das Kalb von Bet-Awen; doch sein Volk", "o. Seine Götzenpriester kreischen verzückt seinetwegen (o. umjubeln es) wegen seiner Pracht, aber", "℘ Zef 1,4"] },
      { number: 6, text: "Auch das wird nach Assur gebracht als Tribut für den König Jareb*. Beschämung wird Ephraim ergreifen, und Israel wird sich schämen wegen seines Ratschlags*.", footnotes: ["d. h. Streiter, o. Streitsüchtiger\n℘ Kap. 5,13", "℘ Kap. 4,19; 11,6"] },
      { number: 7, text: "Vernichtet ist Samaria; sein König treibt wie ein abgeknickter Zweig auf der Wasserfläche." },
      { number: 8, text: "Ausgerottet werden die Höhen von Awen*, Israels Sünde*; Dornen und Disteln werden auf ihren Altären wachsen. Und sie werden zu den Bergen sagen: Bedeckt uns! — und zu den Hügeln: Fallt auf uns!*", footnotes: ["℘ Kap. 8,5.6; Am 1,5; 3,14", "℘ 1Kö 12,30", "℘ Jes 2,19; Lk 23,30; Offb 6,16"] },
      { number: 9, text: "Seit den Tagen von Gibea hast du gesündigt, Israel*. Dort sind sie stehen geblieben. Wird sie nicht in* Gibea der Kampf gegen die Kinder der Widerspenstigkeit erreichen*?", footnotes: ["℘ Kap. 9,9", "o. wie in", "℘ Ri 20,21.25"] },
      { number: 10, text: "Nach meinem Wunsch werde ich sie auch züchtigen, und Völker werden gegen sie versammelt werden, wenn man sie für ihre zweifache Schuld bindet*.", footnotes: ["o. weil sie in ihre zweifache Schuld verstrickt sind\n℘ 1Kö 12,28"] },
      { number: 11, text: "Und Ephraim war doch eine eingewöhnte junge Kuh, die gern drosch. Und ich, als ich an ihrem schönen Nacken vorbeikam, wollte ich Ephraim einspannen. Juda sollte pflügen, Jakob für sich eggen:" },
      { number: 12, text: "»Säet euch nach Gerechtigkeit! Erntet gemäß der Gnade*! Brecht euch einen Neubruch*! Es ist Zeit, den HERRN zu suchen*, damit* er kommt und euch Gerechtigkeit regnen lässt.«*", footnotes: ["o. Bundestreue\n℘ Spr 11,18; Gal 6,8", "℘ Jer 4,3", "℘ Jes 55,6; Am 5,4", "o. bis", "℘ Kap. 6,3; Jes 45,8; 54,14; 2Kor 9,10"] },
      { number: 13, text: "Ihr habt Ungerechtigkeit* gepflügt, Unrecht geerntet*, die Frucht der Lüge gegessen. Weil du auf deinen Weg* vertraut hast, auf die Menge deiner Helden*,", footnotes: ["o. Gottlosigkeit", "℘ Kap. 8,7; 1Sam 24,14; Gal 6,7", "LXX: auf deine Streitwagen; o. auf dein Bogenschießen", "℘ Ps 33,16"] },
      { number: 14, text: "so wird sich Kriegslärm erheben gegen deine Stämme*, und alle deine Festungen werden verwüstet, wie Schalman Bet-Arbeel verwüstete am Tag der Schlacht, da die Mutter samt* den Kindern zerschmettert wurde.", footnotes: ["w. Völker", "o. über"] },
      { number: 15, text: "So hat man euch getan, Bethel*, wegen eurer Bosheit*. Mit dem Morgenrot wird Israels König völlig vernichtet* sein.", footnotes: ["LXX: So werde ich euch tun, Haus Israel", "w. wegen der Bosheit eurer Bosheit", "o. verstummt"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Als Israel jung war, gewann ich es lieb*, und aus Ägypten habe ich meinen Sohn gerufen*.", heading: "Gott bleibt der Heilige: Seine Liebe zu Israel siegt über seinen Zorn", footnotes: ["℘ Jes 43,4; Hes 16,22", "℘ 2Mo 4,22; Mt 2,15"] },
      { number: 2, text: "Sooft ich sie rief, gingen sie von meinem Angesicht weg.* Den Baalim opferten sie, und den Gottesbildern brachten sie Rauchopfer dar*.", footnotes: ["so mit LXX; Mas. T.: Sooft sie (das sind die Propheten) sie riefen, gingen sie von deren Gesicht weg.\n℘ 2Kö 17,14", "℘ Kap. 4,17; 13,2"] },
      { number: 3, text: "Und ich, ich lehrte Ephraim laufen — ich nahm sie immer wieder auf meine Arme* —, aber sie erkannten nicht, dass ich sie heilte*.", footnotes: ["so mit der aram. und syr. Üs. und Vulg.; andere üs.: ich nahm es bei seinen Armen; Mas. T.: er nahm sie auf seine Arme\n℘ 5Mo 1,31; 33,27", "℘ 2Mo 15,26"] },
      { number: 4, text: "Mit menschlichen Tauen zog ich sie, mit Seilen der Liebe*, und ich war ihnen wie solche, die das Joch auf ihren Kinnbacken anheben, und sanft zu ihm gab ich ihm zu essen*.", footnotes: ["℘ Jer 31,3", "Andere üs. mit Textänderung: Und ich war für sie wie die, die ein kleines Kind an ihre Wange heben, ich neigte mich zu ihm hinab und gab ihm zu essen.\n℘ 5Mo 32,12-14"] },
      { number: 5, text: "Es wird nicht ins Land Ägypten zurückkehren. Aber Assur, der wird sein König sein, denn sie weigern sich umzukehren*.", footnotes: ["℘ Kap. 9,3; Jer 8,5; Am 4,6-12; Joh 5,40"] },
      { number: 6, text: "Und das Schwert wird kreisen* in seinen Städten und seinen Schwätzern* ein Ende machen, und es wird fressen wegen ihrer Ratschläge*.", footnotes: ["℘ 3Mo 26,25", "w. ihrem Geschwätz; o. ihren Orakelpriestern", "℘ Kap. 10,6; Jes 30,1"] },
      { number: 7, text: "Aber mein Volk bleibt verstrickt in die Abkehr von mir. Und ruft man es nach oben, bringt man es doch insgesamt nicht dazu, sich zu erheben*.", footnotes: ["℘ Kap. 7,16; Jes 26,10; Jer 7,25.26"] },
      { number: 8, text: "Wie sollte ich dich preisgeben, Ephraim, wie sollte ich dich ausliefern, Israel*? Wie könnte ich dich preisgeben wie Adma, dich Zebojim gleichmachen*? Mein Herz kehrt sich in mir um*, ganz und gar erregt ist all mein Mitleid*.", footnotes: ["℘ Kap. 6,4; Jer 9,6", "℘ 5Mo 29,22", "o. wendet sich gegen mich", "℘ 2Chr 36,15; Jer 31,20"] },
      { number: 9, text: "Nicht ausführen will ich die Glut meines Zornes, will nicht noch einmal Ephraim vernichten*. Denn Gott bin ich und nicht ein Mensch*, in deiner Mitte der Heilige*; ich will nicht in Zornglut kommen. —", footnotes: ["℘ Ps 78,38; 85,4; Jer 30,11", "℘ 4Mo 23,19", "℘ Kap. 12,1"] },
      { number: 10, text: "Hinter dem HERRN werden sie herziehen*; wie ein Löwe wird er brüllen*, ja, er wird brüllen, und zitternd werden die Söhne herbeikommen vom Meer*.", footnotes: ["℘ Jer 50,4", "℘ Jer 25,30; Offb 10,3", "d. h. vom Westen\n℘ Jes 11,11; Sach 8,7.8; 10,10"] },
      { number: 11, text: "Sie werden zitternd herbeikommen aus Ägypten wie ein Vogel und wie eine Taube aus dem Land Assur*. Und ich werde sie in ihren Häusern wohnen lassen*, spricht der HERR*.", footnotes: ["℘ Jes 11,11; Sach 8,7.8; 10,10", "℘ Hes 28,26", "w. ist der Ausspruch des HERRN"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Mit Lüge hat Ephraim mich umringt, mit Betrug* das Haus Israel*. Und Juda ist immer noch schwankend gegenüber Gott* und gegenüber dem Heiligen, der treu ist*.", heading: "Trotz Israels Untreue — Gott bleibt der Herr seines Volkes", footnotes: ["o. Hinterlist", "℘ Kap. 7,1; Ps 78,36", "w. er schweift immer noch umher in Bezug auf Gott\n℘ 2Chr 21,11", "Andere üs. mit Hinzufügung eines Buchstabens: Aber Juda geht noch mit Gott und hält sich treu zu den Heiligen.\n℘ Kap. 11,9"] },
      { number: 2, text: "Ephraim weidet Wind und jagt dem Ostwind nach* den ganzen Tag, es mehrt Lüge* und Gewalttat. Einen Bund schließen sie mit Assur, und Öl wird nach Ägypten gebracht*.", footnotes: ["℘ Hi 15,2", "℘ Kap. 7,1; Ps 78,36", "℘ Kap. 7,11; 8,9.10; 2Kö 17,4; Jes 30,6"] },
      { number: 3, text: "Auch mit Juda* führt der HERR einen Rechtsstreit*. Und er wird Jakob heimsuchen nach seinen Wegen, nach seinen Taten ihm vergelten*.", footnotes: ["Andere nehmen an, dass im Hebr. ursprünglich gestanden hat: Und mit Israel", "℘ Kap. 4,1; 2Kö 17,18-20; Jer 2,9; Mi 6,2", "℘ Kap. 4,9.15; Hes 7,3.27; Am 2,4"] },
      { number: 4, text: "Im Mutterleib hinterging er seinen Bruder*, und in seiner Manneskraft kämpfte er mit Gott*:", footnotes: ["o. packte er seines Bruders Ferse\n℘ 1Mo 25,26", "℘ 1Mo 32,25-30"] },
      { number: 5, text: "*Er kämpfte mit dem Engel* und war überlegen! Er weinte und flehte ihn um Gnade an. In Bethel fand er ihn, und dort redete er mit ihm*.", footnotes: ["Andere üs. mit Textänderung: Aber Gott, nämlich der Engel erwies sich als Herr", "Andere üs. mit Textänderung: Aber Gott, nämlich der Engel erwies sich als Herr", "so LXX und die syr. Üs.; Mas. T.: mit uns\n℘ 1Mo 35,9-15"] },
      { number: 6, text: "Und der HERR, der Gott der Heerscharen — Jahwe ist sein Name* — sprach:", footnotes: ["w. seine Anrufung; d. h. der Name, unter dem Gott angerufen werden will\n℘ 2Mo 3,15; Am 4,13"] },
      { number: 7, text: "Ja, du darfst mit Hilfe deines Gottes zurückkehren*! Nur bewahre Treue* und Recht* und hoffe beständig auf deinen Gott!*", footnotes: ["℘ Kap. 14,2; Joe 2,12", "o. Und du sollst umkehren zu deinem Gott! Bewahre Gnade", "℘ Jes 56,1; Sach 7,9", "℘ 1Mo 49,18"] },
      { number: 8, text: "Ein Händler* ist Israel, in seiner Hand ist eine Waage des Betrugs*, er liebt es zu übervorteilen*.", footnotes: ["o. Ein Kanaanäer; hebr. kanaan; ein abfälliger Ausdruck für einen Händler", "o. der Hinterlist", "℘ Am 8,5; Spr 11,1"] },
      { number: 9, text: "Und Ephraim sagt: Ich bin doch reich geworden, habe mir ein Vermögen erworben*. In all meinem Erwerb wird man mir keine Schuld nachweisen*, die Sünde wäre*.", footnotes: ["℘ Ps 49,7; Sach 11,5", "w. wird man keine Schuld an mir finden", "℘ Spr 30,12.20; Jer 5,27"] },
      { number: 10, text: "Ich aber bin der HERR, dein Gott, vom Land Ägypten her*. Ich lasse dich wieder in Zelten wohnen wie in den Tagen des Festes*.", footnotes: ["℘ Kap. 13,4; 2Mo 20,2", "o. der Begegnung; d. i. vielleicht die Begegnung am Sinai\n℘ 3Mo 23,42"] },
      { number: 11, text: "Und immer wieder habe ich zu den Propheten geredet*, ja, ich ließ Visionen zahlreich sein*, und durch die Propheten gebe ich Gleichnisse*.", footnotes: ["℘ 2Kö 17,13", "℘ 4Mo 12,6", "℘ Hes 17,2"] },
      { number: 12, text: "Wenn Gilead schon Unheil* war*, wahrhaftig, dann sind sie Nichtiges geworden. Sie opferten Stiere in Gilgal*; so sollen auch ihre Altäre wie Steinhaufen* sein an den Furchen des Feldes.", footnotes: ["o. abgöttischer Kult", "℘ Kap. 6,8", "℘ Kap. 4,15", "hebr. kegalim; klingt ähnlich wie »Gilgal«; Gilgal heißt: zusammengerollte Steine"] },
      { number: 13, text: "Und Jakob floh in das Gebiet von Aram*, und Israel diente um eine Frau und hütete Schafe um eine Frau*.", footnotes: ["℘ 5Mo 26,5", "℘ 1Mo 29,20"] },
      { number: 14, text: "Aber durch einen Propheten führte der HERR Israel aus Ägypten herauf, und durch einen Propheten wurde es gehütet*.", footnotes: ["℘ 5Mo 18,15.18; Ps 77,21"] },
      { number: 15, text: "Ephraim hat bittere Kränkung verübt*, und sein Herr wird seine Blutschuld auf ihm lassen* und seine Schmähung ihm vergelten*.", footnotes: ["℘ 2Kö 17,10-17", "℘ Kap. 4,2; Mt 23,35; 27,25", "℘ Mi 6,16"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Wenn Ephraim redete, war Schrecken*; es erhob sich in Israel. Aber es wurde schuldig durch Baal* und starb*.", heading: "Gericht durch Assur wegen Israels Vertrauen auf Götzen und Könige", footnotes: ["℘ Ri 8,1-3", "℘ Kap. 2,10", "℘ Jes 7,8; Röm 6,23"] },
      { number: 2, text: "Und nun fahren sie fort zu sündigen* und machen sich ein gegossenes Bild, aus ihrem Silber Götzenbilder, entsprechend ihrer Kunstfertigkeit*, Arbeit von Handwerkern ist das alles*. Von denen sagt man: Die, die Menschen opfern, küssen Kälber!*", footnotes: ["℘ Jer 8,5", "o. machen sich aus ihrem Silber ein gegossenes Bild, und zwar nach ihrer Vorstellung von Götzenbildern. — LXX und Vulg.: . . . ein gegossenes Bild . . . nach Art der Götterbilder", "w. sein Ganzes\n℘ Kap. 8,4; 10,1; 11,2; Jes 44,11", "o. Die Menschen, die opfern, küssen Kälber. — Andere üs. mit geringfügiger Textänderung: »Ihnen opfert!«, sagt man. Menschen küssen Kälber!; o. »Ihnen schlachtet zum Opfer!«; d. i. den Götzen\n℘ 1Kö 19,18"] },
      { number: 3, text: "Darum werden sie sein wie die Morgenwolke und wie Tau, der früh verschwindet*, wie Spreu, die von der Tenne weht, und wie Rauch aus der Luke*.", footnotes: ["℘ Kap. 6,4; Hi 21,18", "℘ Ps 1,4; Zef 2,2"] },
      { number: 4, text: "Ich aber bin der HERR, dein Gott, vom Land Ägypten her*. Einen Gott außer mir kennst du nicht, und es gibt keinen andern Retter als mich*.", footnotes: ["℘ Kap. 12,10", "℘ Jes 43,11; Jon 2,10; Apg 4,12"] },
      { number: 5, text: "Ich habe dich ja gekannt in der Wüste*, im Land der Gluten*.", footnotes: ["℘ Kap. 5,3; 9,10", "℘ 5Mo 2,7; 8,15; 32,10"] },
      { number: 6, text: "Ihrem Weideplatz entsprechend wurden sie auch satt. Sie wurden satt, und ihr Herz überhob sich; darum vergaßen sie mich*.", footnotes: ["℘ Kap. 8,14; Spr 30,9"] },
      { number: 7, text: "So wurde ich für sie wie ein Löwe, wie ein Leopard laure ich am Weg*.", footnotes: ["℘ Kap. 5,14; Hi 10,16"] },
      { number: 8, text: "Ich falle sie an wie eine Bärin, die der Jungen beraubt ist*, und zerreiße den Verschluss ihres Herzens*. Ich fresse sie dort wie eine Löwin*. Die Tiere des Feldes zerfleischen sie.", footnotes: ["℘ 2Sam 17,8", "d. i. ihre Brust, die mit den Rippen das Herz schützt", "Andere ändern in: Dann fressen sie die Hunde."] },
      { number: 9, text: "Es hat dich zugrunde gerichtet, Israel, dass du gegen mich, gegen deinen Helfer, bist*.", footnotes: ["℘ Kap. 7,15; 14,1; 2Chr 28,23"] },
      { number: 10, text: "Wo ist nun dein König*, dass er dich rette in all deinen Städten, und wo deine Richter, von denen du sagtest: Gib mir einen König und Obersten?*", footnotes: ["℘ Kap. 10,3.15", "℘ 1Sam 8,5.7; Kla 4,20"] },
      { number: 11, text: "Ich gab* dir einen König* in meinem Zorn und nahm* ihn weg in meinem Grimm*.", footnotes: ["o. gebe bzw. nehme", "℘ 1Sam 12,1.13", "o. gebe bzw. nehme", "℘ 1Sam 15,23"] },
      { number: 12, text: "Die Schuld Ephraims ist zusammengebunden*, aufbewahrt seine Sünde*.", footnotes: ["℘ Hi 14,17", "℘ 5Mo 32,34"] },
      { number: 13, text: "Kommen die Geburtswehen für ihn*, ist er ein unverständiger Sohn. Denn wenn es Zeit ist, tritt er nicht ein in den Muttermund*.", footnotes: ["℘ 2Kö 19,3", "w. in die Durchbruchstelle der Kinder\n℘ 1Mo 29,20"] },
      { number: 14, text: "*Aus der Gewalt des Scheol sollte ich sie befreien*, vom Tod sie erlösen?* Wo sind, Tod, deine Dornen? Wo ist*, Scheol, dein Stachel?* Mitleid ist vor meinen Augen verborgen*.", footnotes: ["Andere üs.: Erst aus der Hand des Scheol befreie ich sie; erst aus dem Tod erlöse ich sie.", "o. loskaufen\n℘ Ps 49,16; Jes 25,8", "o. loskaufen", "zwei griech. Üs. und Vulg.: Ich bin deine Pest, Tod, ich bin", "℘ 1Kor 15,55; 2Tim 1,10", "℘ Kap. 7,10"] },
      { number: 15, text: "Denn er trennt zwischen* Brüdern*. Wie ein Ostwind wird der Feind kommen*, ein Wind des HERRN, der aus der Wüste steigt. Dann trocknet sein Brunnen aus, und seine Quelle versiegt*. Er* plündert den Schatz, alles kostbare Gerät.", footnotes: ["o. er gedeiht unter", "℘ 1Mo 49,22", "℘ Kap. 4,19", "℘ Hes 19,12", "d. i. der als Ostwind kommende Eroberer"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Samaria* wird büßen, denn es ist widerspenstig gewesen gegen seinen Gott. Sie werden durchs Schwert fallen, ihre Kinder werden zerschmettert und ihre Schwangeren aufgeschlitzt*.", footnotes: ["℘ Hes 16,46", "℘ Kap. 9,13; 13,9; 2Kö 8,12"] },
      { number: 2, text: "Kehr um, Israel, bis zum HERRN, deinem Gott!* Denn du bist gestürzt durch deine Schuld*.", heading: "Mahnung zur Umkehr — Verheißung des zukünftigen Heils", footnotes: ["℘ Kap. 12,7; Jes 44,22; Apg 3,19", "℘ Kap. 5,5; 2Sam 24,10"] },
      { number: 3, text: "Nehmt Worte mit euch und kehrt zum HERRN um! Sagt zu ihm: Vergib alle Schuld* und nimm an, was gut ist! Wir wollen die Frucht unserer Lippen als Opfer darbringen.*", footnotes: ["℘ Lk 18,13", "so mit LXX und der syr. Üs.; Mas. T.: Wir wollen als Stiere unsere Lippen als Opfer darbringen.\n℘ Jon 2,10"] },
      { number: 4, text: "Assur soll uns nicht retten, auf Pferden wollen wir nicht reiten* und zum Machwerk unserer Hände nicht mehr sagen: Unser Gott!* Denn bei dir findet die Waise Erbarmen*.", footnotes: ["℘ Ps 20,8", "℘ Kap. 2,19", "℘ Ps 10,14"] },
      { number: 5, text: "Ich will ihre Abtrünnigkeit heilen*, will sie aus freiem Antrieb lieben*. Denn mein Zorn hat sich von ihm abgewandt*.", footnotes: ["℘ Jes 57,18.19; Jer 3,22", "℘ Kap. 6,3; Jer 32,41", "℘ Jes 12,1; Mi 7,18"] },
      { number: 6, text: "Ich werde für Israel sein wie der Tau*. Blühen soll es wie die Lilie, und seine Wurzeln schlagen wie der Libanon*.", footnotes: ["℘ Kap. 6,3", "℘ Jes 27,6; 35,2; 66,14"] },
      { number: 7, text: "Seine Triebe sollen sich ausbreiten, und seine Pracht soll sein wie der Ölbaum* und sein Geruch wie der des Libanon*.", footnotes: ["℘ Ps 52,10", "℘ Hl 4,11"] },
      { number: 8, text: "Es kehren zurück, die in seinem Schatten wohnen*, sie werden wieder Getreide anbauen* und blühen wie ein Weinstock, dessen Ruf* wie der Wein vom Libanon ist.", footnotes: ["Andere üs. mit LXX und Änderung an einem Wort: Sie werden wieder in meinem Schatten wohnen", "w. sie werden das Getreide beleben", "w. dessen Erwähnung"] },
      { number: 9, text: "Ephraim wird sagen: Was soll ich noch mit den Götzen?* — Ich, ich habe ihn erhört und auf ihn geblickt*. — Ich bin wie ein grüner Wacholder, nur an mir* wird Frucht für dich gefunden*.", footnotes: ["o. Ephraim, was soll ich noch mit den Götzen? — LXX: Ephraim, was ist ihm und den Götzen noch gemeinsam?\n℘ Jes 17,8; Hes 11,18; 36,25", "o. und ihn beglückt\n℘ Jer 29,12; Sach 10,6", "w. von mir her", "℘ Joh 15,5"] },
      { number: 10, text: "Wer ist weise, dass er dies versteht? Wer ist verständig, dass er es erkennt*? Denn die Wege des HERRN sind gerade. Die Gerechten werden darauf gehen*, die Abtrünnigen* aber werden darauf stürzen*.", footnotes: ["℘ Dan 12,10", "℘ Jes 35,8; Jak 3,13", "o. die Treulosen", "℘ Spr 10,29"] },
    ]},
  ]
};
